insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_weekly_earnings,median_hourly_earnings,annualised_median_salary,all_occupations_median_weekly,part_time_share_pct,female_share_pct,median_age,average_full_time_hours,vacancies_three_month_avg,vacancy_period,vacancy_yoy_pct,employment_growth_5y_pct,employment_growth_10y_pct,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values ('AU:sustainability-specialist','2026-05-01',null,null,null,null,1852,null,null,null,null,443.33333,'2026-05-01',-5.20,8.90,16.64,0,0,5,0,13,0,5,5,3,31,'career-opportunity-v1','provisional',jsonb_build_object('classification_scope','No standalone current OSCA Sustainability Specialist exists. OSCA 244431 Environmental Consultant is a related proxy because it explicitly includes advice to improve organisational sustainability performance.','proxy_profile',jsonb_build_object('employment_total',5100,'part_time_share_pct',25,'female_share_pct',45,'median_age',39,'average_full_time_hours',44,'scope','ANZSCO 234312 Environmental Consultant proxy only; not promoted to primary Sustainability Specialist metrics'),'earnings_scope','Six-digit 234312 earnings are unavailable and broader 2343 earnings are context only; primary salary remains null.','vacancy_scope','Broader 2343 vacancies were 443.33333 in May 2026 versus 467.66667 in May 2025, about -5.20% year on year; no exact intensity or trend credit.','projection_scope','Broader 2343 projections are +8.90% to 2030 and +16.64% to 2035; partial growth credit only.','shortage_note','JSA 2025 OSL records OSCA 244431 Environmental Consultant as No Shortage nationally, with SA and NT in shortage.','visa_basis','The current CSOL includes Environmental Consultant 234312 / VETASSESS Group A, but it is only a proxy for canonical Sustainability Specialist, so partial visa credit is used.','entry_level_basis','Deakin Bachelor of Environmental Science and Sustainability 116267J is a current three-year undergraduate route; Master of Sustainability 108875G is a current 1.5-year graduate route.','score_note','All proxy labour-market evidence is clearly scoped and primary employment and earnings remain null.'),'2026-08-09') on conflict (profile_key,as_of_date) do update set employment_total=excluded.employment_total,median_weekly_earnings=excluded.median_weekly_earnings,median_hourly_earnings=excluded.median_hourly_earnings,annualised_median_salary=excluded.annualised_median_salary,all_occupations_median_weekly=excluded.all_occupations_median_weekly,part_time_share_pct=excluded.part_time_share_pct,female_share_pct=excluded.female_share_pct,median_age=excluded.median_age,average_full_time_hours=excluded.average_full_time_hours,vacancies_three_month_avg=excluded.vacancies_three_month_avg,vacancy_period=excluded.vacancy_period,vacancy_yoy_pct=excluded.vacancy_yoy_pct,employment_growth_5y_pct=excluded.employment_growth_5y_pct,employment_growth_10y_pct=excluded.employment_growth_10y_pct,shortage_component=excluded.shortage_component,vacancy_intensity_component=excluded.vacancy_intensity_component,employer_diversity_component=excluded.employer_diversity_component,vacancy_trend_component=excluded.vacancy_trend_component,entry_level_component=excluded.entry_level_component,salary_component=excluded.salary_component,growth_component=excluded.growth_component,visa_component=excluded.visa_component,entry_burden_component=excluded.entry_burden_component,opportunity_score=excluded.opportunity_score,score_methodology_version=excluded.score_methodology_version,score_status=excluded.score_status,score_evidence=excluded.score_evidence,source_checked_at=excluded.source_checked_at;
